import json
import os
from typing import Dict, Any, List


def load_prompt_package(package_path: str) -> Dict[str, Any]:
    """Load and validate a prompt package JSON file."""
    if not os.path.exists(package_path):
        raise FileNotFoundError(f"Prompt package not found: {package_path}")

    with open(package_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Required top-level keys
    required_keys = ['status', 'result']
    for key in required_keys:
        if key not in data:
            raise ValueError(f"Prompt package missing required key: {key}")

    if data['status'] != 'success':
        raise ValueError(f"Prompt package status is not 'success': {data['status']}")

    result = data['result']
    required_result_keys = ['execution_order', 'prompt_modules']
    for key in required_result_keys:
        if key not in result:
            raise ValueError(f"Prompt package result missing required key: {key}")

    # Validate prompt_modules structure
    prompt_modules = result['prompt_modules']
    for module_name, module in prompt_modules.items():
        if not isinstance(module, dict):
            raise ValueError(f"Prompt module {module_name} is not a dict")
        required_module_keys = ['prompt_text', 'output_contract', 'allowed_field_paths']
        for key in required_module_keys:
            if key not in module:
                raise ValueError(f"Prompt module {module_name} missing required key: {key}")

    return data


def get_prompt_module(package: Dict[str, Any], module_name: str) -> Dict[str, Any]:
    """Retrieve a specific prompt module from a loaded package."""
    modules = package['result']['prompt_modules']
    if module_name not in modules:
        raise KeyError(f"Prompt module '{module_name}' not found in package")
    return modules[module_name]


def get_execution_order(package: Dict[str, Any]) -> List[str]:
    """Get the execution order from a prompt package."""
    return package['result']['execution_order']


def get_workflow_execution_order(package: Dict[str, Any]) -> List[str]:
    """Get the workflow execution order if present, else empty list."""
    return package['result'].get('workflow_execution_order', [])

import re
from typing import Dict, Any, List, Tuple


def validate_field_path_control(prompt_text: str) -> Tuple[bool, List[str]]:
    """Check if prompt includes field_path control keywords."""
    keywords = ['field_path', 'field paths', 'allowed field']
    found = []
    for kw in keywords:
        if re.search(rf'\b{re.escape(kw)}\b', prompt_text, re.IGNORECASE):
            found.append(kw)
    return len(found) > 0, found


def validate_json_contract(prompt_text: str) -> Tuple[bool, List[str]]:
    """Check if prompt includes JSON contract keywords."""
    keywords = ['json', 'valid json', 'json only']
    found = []
    for kw in keywords:
        if re.search(rf'\b{re.escape(kw)}\b', prompt_text, re.IGNORECASE):
            found.append(kw)
    return len(found) > 0, found


def validate_evidence_provenance(prompt_text: str) -> Tuple[bool, List[str]]:
    """Check if prompt includes evidence provenance keywords."""
    keywords = ['evidence', 'provenance', 'source', 'quote', 'span', 'caption', 'ocr']
    found = []
    for kw in keywords:
        if re.search(rf'\b{re.escape(kw)}\b', prompt_text, re.IGNORECASE):
            found.append(kw)
    return len(found) > 0, found


def validate_anti_hallucination(prompt_text: str) -> Tuple[bool, List[str]]:
    """Check if prompt includes anti-hallucination keywords."""
    keywords = ['do not invent', 'never invent', 'hallucination', 'unsupported', 'missing_reason']
    found = []
    for kw in keywords:
        if re.search(rf'\b{re.escape(kw)}\b', prompt_text, re.IGNORECASE):
            found.append(kw)
    return len(found) > 0, found


def validate_prompt_module(module: Dict[str, Any]) -> Dict[str, Any]:
    """Validate a single prompt module against quality criteria."""
    prompt_text = module.get('prompt_text', '')
    checks = [
        ('field_path_control', validate_field_path_control(prompt_text)),
        ('json_contract', validate_json_contract(prompt_text)),
        ('evidence_provenance', validate_evidence_provenance(prompt_text)),
        ('anti_hallucination', validate_anti_hallucination(prompt_text)),
    ]

    results = {}
    for name, (passed, keywords) in checks:
        results[name] = {
            'passed': passed,
            'keywords_found': keywords,
            'severity': 'medium' if name == 'field_path_control' else 'low'
        }
    return results


def validate_prompt_package(package: Dict[str, Any]) -> Dict[str, Any]:
    """Validate all prompt modules in a package."""
    modules = package['result']['prompt_modules']
    validation_results = {}
    all_passed = True
    warnings = []

    for module_name, module in modules.items():
        module_results = validate_prompt_module(module)
        validation_results[module_name] = module_results

        for check_name, check_result in module_results.items():
            if not check_result['passed']:
                all_passed = False
                if check_result['severity'] == 'medium':
                    warnings.append(f"Module '{module_name}' failed {check_name} check")

    return {
        'all_passed': all_passed,
        'validation_results': validation_results,
        'warnings': warnings
    }

import json
import logging
from abc import ABC, abstractmethod
from typing import Dict, Any, Optional

logger = logging.getLogger(__name__)


class AgentExecutor(ABC):
    """Abstract base class for executing an extraction agent."""

    def __init__(self, prompt_module: Dict[str, Any], dry_run: bool = False):
        self.prompt_module = prompt_module
        self.dry_run = dry_run
        self.prompt_text = prompt_module.get('prompt_text', '')
        self.output_contract = prompt_module.get('output_contract', {})
        self.allowed_field_paths = prompt_module.get('allowed_field_paths', [])

    @abstractmethod
    def prepare_input(self, paper_data: Dict[str, Any]) -> Dict[str, Any]:
        """Prepare input for the agent from paper data."""
        pass

    def call_llm(self, input_data: Dict[str, Any]) -> str:
        """Call LLM API with the prepared input."""
        if self.dry_run:
            logger.info("Dry-run mode: simulating LLM call")
            # Return a mock response that passes validation
            mock_response = {
                "status": "success",
                "data": {},
                "evidence": [],
                "missing_reason": "dry_run"
            }
            return json.dumps(mock_response)

        # TODO: Integrate with actual LLM API
        # This is a placeholder for real implementation
        raise NotImplementedError("LLM API integration not implemented")

    def parse_output(self, llm_output: str) -> Dict[str, Any]:
        """Parse and validate LLM output against output contract."""
        try:
            parsed = json.loads(llm_output)
        except json.JSONDecodeError as e:
            logger.error(f"Failed to parse LLM output as JSON: {e}")
            return {
                "status": "error",
                "error": f"JSON decode error: {e}",
                "raw_output": llm_output
            }

        # Basic validation against output contract
        if 'status' not in parsed:
            parsed['status'] = 'unknown'

        return parsed

    def execute(self, paper_data: Dict[str, Any]) -> Dict[str, Any]:
        """Execute the agent on paper data."""
        logger.info(f"Executing {self.__class__.__name__}")
        input_data = self.prepare_input(paper_data)
        llm_output = self.call_llm(input_data)
        result = self.parse_output(llm_output)
        return result


class ClassificationAgent(AgentExecutor):
    """Agent for paper classification."""

    def prepare_input(self, paper_data: Dict[str, Any]) -> Dict[str, Any]:
        # For classification, we might use paper title, abstract, sections
        return {
            "paper_text": paper_data.get('full_text', ''),
            "prompt": self.prompt_text
        }


class SectionExtractionAgent(AgentExecutor):
    """Agent for section-specific extraction."""

    def __init__(self, prompt_module: Dict[str, Any], section_name: str, dry_run: bool = False):
        super().__init__(prompt_module, dry_run)
        self.section_name = section_name

    def prepare_input(self, paper_data: Dict[str, Any]) -> Dict[str, Any]:
        # Extract the specific section text from paper data
        section_text = paper_data.get('sections', {}).get(self.section_name, '')
        return {
            "section_text": section_text,
            "section_name": self.section_name,
            "prompt": self.prompt_text
        }


class FigureExtractionAgent(AgentExecutor):
    """Agent for figure/table extraction."""

    def prepare_input(self, paper_data: Dict[str, Any]) -> Dict[str, Any]:
        # Extract figure data (captions, OCR text, etc.)
        figures = paper_data.get('figures', [])
        return {
            "figures": figures,
            "prompt": self.prompt_text
        }


class PostprocessRepairAgent(AgentExecutor):
    """Agent for post-processing and repair."""

    def prepare_input(self, paper_data: Dict[str, Any]) -> Dict[str, Any]:
        # Use accumulated extraction results for repair
        previous_results = paper_data.get('extraction_results', {})
        return {
            "previous_results": previous_results,
            "prompt": self.prompt_text
        }
